ass="alert <?= $type==='error'?'alert-error':($type==='warning'?'alert-warning':'') ?>" role="<?= $type==='error'?'alert':'status' ?>"><?= Html::encode($flash) ?></div><?php endforeach ?><?= $content ?></main><footer><strong>绿茵视界</strong><span>世界杯赛事数据与球迷互动平台</span><span>绿茵数据团队 · 互联网数据库开发课程设计</span></footer><?php $this->endBody() ?></body></html><?php $this->endPage() ?>
